9	// AppError represents a structured API error response.
10	type AppError struct {
11		Code    int    `json:"code"`
12		Message string `json:"message"`
13		Detail  string `json:"detail,omitempty"`
14	}
15	
16	// Error implements the error interface.
17	func (e *AppError) Error() string {
18		if e.Detail != "" {
19			return e.Message + ": " + e.Detail
20		}
21		return e.Message
22	}
23	
24	// NewBadRequest creates a 400 Bad Request error.
25	func NewBadRequest(detail string) *AppError {
26		return &AppError{
27			Code:    http.StatusBadRequest,
28			Message: "Bad Request",
29			Detail:  detail,
30		}
31	}
32	
33	// NewNotFound creates a 404 Not Found error.
34	func NewNotFound(detail string) *AppError {
35		return &AppError{
36			Code:    http.StatusNotFound,
37			Message: "Not Found",
38			Detail:  detail,
39		}
40	}
