98	// ErrorHandler is a Gin middleware that catches errors set via c.Error()
99	// and returns a JSON error response.
100	func ErrorHandler() gin.HandlerFunc {
101		return func(c *gin.Context) {
102			c.Next()
103	
104			if len(c.Errors) > 0 {
105				err := c.Errors.Last().Err
106				if quotaErr, ok := err.(*QuotaError); ok {
107					c.JSON(quotaErr.Code, quotaErr)
108				} else if appErr, ok := err.(*AppError); ok {
